        )

    dest_dir.mkdir(parents=True, exist_ok=True)
    out = run_gdrive_cli(["readonly", "ls", folder_id, "--max", "200", "--json"])
    data = json.loads(out)
    items = data if isinstance(data, list) else data.get("files", data.get("items", []))

    img_exts = {".jpg", ".jpeg", ".png"}
    vid_exts = {".mov", ".mp4"}

    img_items = [
        it for it in items if pathlib.Path(it.get("name", "")).suffix.lower() in img_exts
    ]
    vid_items = [
        it for it in items if pathlib.Path(it.get("name", "")).suffix.lower() in vid_exts
    ]
    img_items.sort(key=lambda x: x.get("name", ""))
    vid_items.sort(key=lambda x: x.get("name", ""))

    # When a shoot folder has dozens of IMG_*.JPG bursts, sample representative photos across clusters
    selected_imgs = img_items
    if len(img_items) > 8:
        n = len(img_items)
        indices = sorted({0, n // 4, n // 2, (3 * n) // 4, n - 1})
