    # Sample up to max_videos representative video clips across chronological shoot phases
    selected_vids = vid_items
    if max_videos == 0:
        selected_vids = []
    elif len(vid_items) > max_videos:
        vn = len(vid_items)
        v_indices = sorted({int(round(i * (vn - 1) / (max_videos - 1))) for i in range(max_videos)})
        selected_vids = [vid_items[i] for i in v_indices]

    downloaded: List[pathlib.Path] = []
    for item in selected_imgs + selected_vids:
        name = item.get("name", "")
        file_id = item.get("id", "")
        if not file_id:
            continue
        target_path = dest_dir / name
        if target_path.exists() and target_path.stat().st_size > 0:
