def extract_frame_ffmpeg(
    video_path: pathlib.Path,
    out_jpg: pathlib.Path,
    ss: float = 0.5,
    vf: str = "eq=brightness=0.03:gamma=1.06:saturation=1.05",
) -> bool:
    """Extract a single high-quality JPEG frame from a video clip using ffmpeg."""
    cmd = [
        "ffmpeg",
        "-y",
        "-hide_banner",
        "-loglevel",
        "error",
        "-ss",
        f"{max(0.0, ss):.3f}",
        "-i",
        str(video_path),
    ]
    if vf:
        cmd += ["-vf", vf]
    cmd += ["-frames:v", "1", "-q:v", "2", str(out_jpg)]
    res = subprocess.run(cmd, capture_output=True)
    return res.returncode == 0 and out_jpg.exists() and out_jpg.stat().st_size > 0


